// Generated by OSL (@osl/backend-drizzle-next). The Board page: a board of Task rows and a detail pane for the selected one.
// Do not edit: this file is rewritten on every osl generate.

"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { ArrowLeft, Plus } from "lucide-react";
import { Fragment, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FormRow, ListSkeleton, Pane, PaneHeader, PaneSkeleton, RowError, formatDateTime, selectClass, splitList, text } from "../ui";

type Row = Outputs["tasks"]["list"]["data"][number];
type Detail = Outputs["tasks"]["get"];
type Input<K extends keyof Inputs["tasks"]> = Inputs["tasks"][K];

const PAGE_SIZE = 200;
const KEY = ["tasks"] as const;

function idOf(raw: string) {
  return Number(raw);
}

function canCreate(user: SessionUser | null): boolean {
  return true;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return (true && String(row.status) !== "done");
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return true;
}

function canComplete(user: SessionUser | null, row: Detail): boolean {
  return (true && String(row.status) !== "done");
}

function canClearDone(user: SessionUser | null): boolean {
  return true;
}

const TASKS_FIELDS = ["title", "status", "estimate_hours", "due_on", "assignee", "project_id"] as const;
type TasksField = (typeof TASKS_FIELDS)[number];

type TasksValues = {
  title: string;
  status: "todo" | "doing" | "done";
  estimate_hours: string;
  due_on: string;
  assignee: string;
  project_id: string;
};

const EMPTY_TASKS: TasksValues = {
  title: "",
  status: "todo",
  estimate_hours: "",
  due_on: "",
  assignee: "",
  project_id: ""
};

const TASKS_CREATE: readonly TasksField[] = ["title", "status", "estimate_hours", "due_on", "assignee", "project_id"];

function toTasksCreateInput(v: TasksValues): Input<"create"> {
  return {
    title: v.title,
    status: (v.status || undefined),
    estimate_hours: (v.estimate_hours || null),
    due_on: (v.due_on || null),
    assignee: (v.assignee || null),
    project_id: (v.project_id === "" ? null : Number(v.project_id))
  };
}

const TASKS_UPDATE: readonly TasksField[] = ["title", "status", "estimate_hours", "due_on", "assignee", "project_id"];

function toTasksUpdateInput(v: TasksValues): Input<"update">["data"] {
  return {
    title: v.title,
    status: v.status,
    estimate_hours: (v.estimate_hours || null),
    due_on: (v.due_on || null),
    assignee: (v.assignee || null),
    project_id: (v.project_id === "" ? null : Number(v.project_id))
  };
}

function tasksFromRow(row: Detail): TasksValues {
  return {
    title: text(row.title),
    status: row.status,
    estimate_hours: text(row.estimate_hours),
    due_on: text(row.due_on).slice(0, 10),
    assignee: text(row.assignee),
    project_id: text(row.project_id)
  };
}

/** Picks a Project from the projects resource */
function ProjectIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["projects", "list", { page_size: 200 }], queryFn: () => client.projects.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type TasksSetter = <K extends keyof TasksValues>(key: K, value: TasksValues[K]) => void;

function renderTasksField(field: TasksField, values: TasksValues, set: TasksSetter) {
  switch (field) {
    case "title":
      return (
      <FormRow label="Title" htmlFor="title">
        <Input id="title" type="text" maxLength={200} value={values.title} onChange={e => set("title", e.target.value)} required />
      </FormRow>
      );
    case "status":
      return (
      <FormRow label="Status" htmlFor="status">
        <select id="status" className={selectClass} value={values.status} onChange={e => set("status", e.target.value as TasksValues["status"])}>
          <option value="todo">todo</option>
          <option value="doing">doing</option>
          <option value="done">done</option>
        </select>
      </FormRow>
      );
    case "estimate_hours":
      return (
      <FormRow label="Estimate Hours" htmlFor="estimate_hours">
        <Input id="estimate_hours" type="number" step="any" value={values.estimate_hours} onChange={e => set("estimate_hours", e.target.value)} />
      </FormRow>
      );
    case "due_on":
      return (
      <FormRow label="Due On" htmlFor="due_on">
        <Input id="due_on" type="date" value={values.due_on} onChange={e => set("due_on", e.target.value)} />
      </FormRow>
      );
    case "assignee":
      return (
      <FormRow label="Assignee" htmlFor="assignee">
        <Input id="assignee" type="text" maxLength={80} value={values.assignee} onChange={e => set("assignee", e.target.value)} />
      </FormRow>
      );
    case "project_id":
      return (
      <FormRow label="Project" htmlFor="project_id">
        <ProjectIdPicker id="project_id" value={values.project_id} onChange={value => set("project_id", value)} allowEmpty={true} />
      </FormRow>
      );
  }
}

function TasksForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly TasksField[];
  initial: TasksValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: TasksValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<TasksValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: TasksSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderTasksField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

export function TasksLayout({ children }: { children: ReactNode }) {
  return <div className="h-full min-h-0 overflow-hidden">{children}</div>;
}

const BOARD_INPUT = { page: 1, page_size: PAGE_SIZE } as Inputs["tasks"]["list"];
const COLUMNS = ["todo", "doing", "done"] as const;
type Column = (typeof COLUMNS)[number];

export function TasksIndex() {
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const boardInput = { ...BOARD_INPUT } as Inputs["tasks"]["list"];
  const boardKey = [...KEY, "list", boardInput] as const;
  const list = useQuery({ queryKey: boardKey, queryFn: () => client.tasks.list(boardInput) });
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const router = useRouter();
  const queryClient = useQueryClient();
  const clear_doneAction = useMutation({
    mutationFn: (input: Inputs["tasks"]["clear_done"]) => client.tasks.clear_done(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const move = useMutation({
    mutationFn: ({ id, status }: { id: Row["id"]; status: Column }) => client.tasks.update({ id, data: { status } }),
    onMutate: async ({ id, status }) => {
      await queryClient.cancelQueries({ queryKey: boardKey });
      const previous = queryClient.getQueryData<Outputs["tasks"]["list"]>(boardKey);
      if (previous) {
        queryClient.setQueryData<Outputs["tasks"]["list"]>(boardKey, {
          ...previous,
          data: previous.data.map(row => (row.id === id ? { ...row, status } : row))
        });
      }
      return { previous };
    },
    onError: (_error, _input, context) => {
      if (context?.previous) queryClient.setQueryData(boardKey, context.previous);
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: KEY })
  });
  const rows = list.data?.data ?? [];
  return (
    <div className="flex h-full min-h-0 flex-col">
      <PaneHeader title="Board" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/tasks/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New task">
              <Plus />
            </Link>
          ) : null}
          {canClearDone(user) ? (
            <Button variant="outline" size="sm" disabled={clear_doneAction.isPending} onClick={() => clear_doneAction.mutate({})}>
              Clear Done
            </Button>
          ) : null}
      </PaneHeader>

        <ErrorNote error={clear_doneAction.error} className="m-4" />
      <ErrorNote error={move.error ?? list.error} className="m-4" />
      {list.isPending ? (
        <ListSkeleton />
      ) : (
        <div className="flex min-h-0 flex-1 gap-4 overflow-x-auto p-4">
          {COLUMNS.map(column => (
            <section
              key={column}
              className="flex w-72 shrink-0 flex-col rounded-lg border border-border bg-muted/30"
              onDragOver={event => event.preventDefault()}
              onDrop={event => {
                event.preventDefault();
                const dragged = event.dataTransfer.getData("text/plain");
                const row = rows.find(r => text(r.id) === dragged);
                if (row && row.status !== column) move.mutate({ id: row.id, status: column });
              }}
            >
              <header className="flex items-center justify-between px-3 py-2 text-sm font-medium">
                <span>{column}</span>
                <span className="text-xs text-muted-foreground">{rows.filter(r => r.status === column).length}</span>
              </header>
              <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-2">
                {rows
                  .filter(r => r.status === column)
                  .map((row: Row) => (
                    <div
                      key={text(row.id)}
                      draggable
                      onDragStart={event => {
                        event.dataTransfer.setData("text/plain", text(row.id));
                        event.dataTransfer.effectAllowed = "move";
                      }}
                      onClick={() => router.push(`/tasks/${text(row.id)}`)}
                      className="cursor-grab rounded-md border border-border bg-card p-3 text-sm shadow-xs hover:bg-accent/40 active:cursor-grabbing"
                    >
                      <div className="font-medium">{text(row.title) || text(row.id)}</div>
                      <div className="mt-1 text-xs text-muted-foreground">{[text(row.due_on)].filter(Boolean).join(" · ")}</div>
                    </div>
                  ))}
              </div>
            </section>
          ))}
        </div>
      )}
    </div>
  );
}

export function TasksNew() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.tasks.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/tasks/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New task" actions={<Link href="/tasks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <TasksForm
        fields={TASKS_CREATE}
        initial={EMPTY_TASKS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toTasksCreateInput(values))}
      />
    </Pane>
  );
}

export function TasksDetail() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.tasks.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["tasks"]["update"]) => client.tasks.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["tasks"]["delete"]) => client.tasks.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/tasks");
    }
  });
  const completeAction = useMutation({
    mutationFn: (input: Inputs["tasks"]["complete"]) => client.tasks.complete(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Task " + text(row.id)}
      actions={
        <>
          <Link href="/tasks" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canComplete(user, row) ? (
            <Button variant="outline" size="sm" disabled={completeAction.isPending} onClick={() => completeAction.mutate({ id })}>
              Complete
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this task?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={completeAction.error} className="mb-4" />
      {editing ? (
        <TasksForm
          fields={TASKS_UPDATE}
          initial={tasksFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toTasksUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Status">{row.status == null ? "—" : <Badge variant="secondary">{text(row.status)}</Badge>}</FieldRow>
        <FieldRow label="Estimate Hours">{text(row.estimate_hours) || "—"}</FieldRow>
        <FieldRow label="Due On">{text(row.due_on) || "—"}</FieldRow>
        <FieldRow label="Assignee">{text(row.assignee) || "—"}</FieldRow>
        <FieldRow label="Project">{row.project_id != null ? <Link href={`/projects/${text(row.project_id)}`} className="hover:underline">{(row.project ? text(row.project.name) : text(row.project_id)) || "—"}</Link> : (row.project ? text(row.project.name) : text(row.project_id)) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Note">{row.note ? text(row.note.body) : "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}
